using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // Replace with your actual connection settings
        options.UseCosmos("AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
                         "ProductsDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1: EF Core 9 renamed the discriminator JSON property
            // from "Discriminator" to "$type". Preserve old name for existing documents
            // and raw SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2: EF Core 9 changed the id format from
            // "Product|<key>" to just "<key>". Use a custom value generator
            // to keep writing the legacy "Product|<key>" format so existing
            // 500K documents remain queryable by their original id.
            entity.Property<string>("__id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }
}

/// <summary>
/// Reproduces the EF Core 8 id format: "EntityTypeName|KeyValue"
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var key = entry.Property("Id").CurrentValue;
        return $"Product|{key}";
    }
}

